CREATE OR REPLACE FUNCTION hr_public.can_access_document(p_user_id uuid, p_document_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    user_role TEXT;
    has_access BOOLEAN;
BEGIN
    -- Get user role from users table
    SELECT role INTO user_role FROM hr_public.users WHERE id = p_user_id;

    -- Admin can access everything
    IF user_role = 'super_admin' THEN
        RETURN TRUE;
    END IF;

    -- HR can access all non-deleted documents
    IF user_role = 'hr_manager' THEN
        RETURN EXISTS (
            SELECT 1 FROM hr_public.documents
            WHERE id = p_document_id AND is_deleted = FALSE
        );
    END IF;

    -- Check if user has direct assignment or department assignment
    SELECT EXISTS (
        SELECT 1 FROM hr_public.document_assignments da
        WHERE da.document_id = p_document_id
        AND da.assignment_status = 'active'
        AND (
            da.employee_id = p_user_id
            OR da.department_id IN (
                SELECT department_id FROM hr_public.users WHERE id = p_user_id
            )
        )
    ) INTO has_access;

    -- If manager, also check direct reports
    IF NOT has_access AND user_role IN ('manager', 'hr_manager') THEN
        SELECT EXISTS (
            WITH RECURSIVE direct_reports AS (
                SELECT id FROM hr_public.users WHERE id = p_user_id
                UNION
                SELECT u.id FROM hr_public.users u
                JOIN direct_reports dr ON u.manager_id = dr.id
            )
            SELECT 1 FROM hr_public.document_assignments da
            JOIN direct_reports dr ON da.employee_id = dr.id
            WHERE da.document_id = p_document_id
            AND da.assignment_status = 'active'
        ) INTO has_access;
    END IF;

    RETURN has_access;
END;
$function$

CREATE OR REPLACE FUNCTION hr_public.create_access_log_partition(partition_date date)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    partition_name TEXT;
    start_date DATE;
    end_date DATE;
BEGIN
    partition_name := 'document_access_logs_' || to_char(partition_date, 'YYYY_MM');
    start_date := date_trunc('month', partition_date);
    end_date := start_date + INTERVAL '1 month';

    EXECUTE format('
        CREATE TABLE IF NOT EXISTS hr_public.%I PARTITION OF hr_public.document_access_logs
        FOR VALUES FROM (%L) TO (%L)
    ', partition_name, start_date, end_date);
END;
$function$

CREATE OR REPLACE FUNCTION hr_public.decrypt_key_data(p_encrypted_key_data bytea, p_key_identifier character varying)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    encryption_password TEXT;
BEGIN
    encryption_password := p_key_identifier || '_SERVER_SECRET_KEY_PLACEHOLDER';

    -- Decrypt using pgcrypto
    RETURN pgp_sym_decrypt_bytea(p_encrypted_key_data, encryption_password);
END;
$function$

CREATE OR REPLACE FUNCTION hr_public.execute_rollback(p_log_id uuid, p_reason text, p_strategy text DEFAULT 'force'::text, p_executed_by uuid DEFAULT NULL::uuid)
 RETURNS TABLE(success boolean, new_log_id uuid, error text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_target_log hr_public.activity_logs%ROWTYPE;
    v_resource_table TEXT;
    v_resource_id UUID;
    v_before_snapshot JSONB;
    v_after_snapshot JSONB;
    v_new_log_id UUID;
    v_current_user_id UUID;
BEGIN
    -- Get current user ID if not provided
    v_current_user_id := COALESCE(
        p_executed_by,
        NULLIF(current_setting('jwt.claims.user_id', true), '')::UUID
    );

    -- Validate user permissions (must be super_admin)
    IF current_setting('jwt.claims.role', true) != 'super_admin' THEN
        RETURN QUERY SELECT FALSE, NULL::UUID, 'Only super_admin can execute rollbacks'::TEXT;
        RETURN;
    END IF;

    -- Validate reason
    IF p_reason IS NULL OR LENGTH(TRIM(p_reason)) < 10 THEN
        RETURN QUERY SELECT FALSE, NULL::UUID, 'Rollback reason must be at least 10 characters'::TEXT;
        RETURN;
    END IF;

    -- Get the target activity log
    SELECT * INTO v_target_log
    FROM hr_public.activity_logs
    WHERE id = p_log_id;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, NULL::UUID, 'Activity log not found'::TEXT;
        RETURN;
    END IF;

    -- Validate: Cannot rollback a rollback
    IF v_target_log.is_rollback = TRUE THEN
        RETURN QUERY SELECT FALSE, NULL::UUID, 'Cannot rollback a rollback operation'::TEXT;
        RETURN;
    END IF;

    -- Validate: Cannot rollback VIEW operations
    IF UPPER(v_target_log.action) = 'VIEW' THEN
        RETURN QUERY SELECT FALSE, NULL::UUID, 'Cannot rollback view operations'::TEXT;
        RETURN;
    END IF;

    -- Check if already rolled back
    IF EXISTS (
        SELECT 1 FROM hr_public.activity_logs
        WHERE rolled_back_log_id = p_log_id
    ) THEN
        RETURN QUERY SELECT FALSE, NULL::UUID, 'This operation has already been rolled back'::TEXT;
        RETURN;
    END IF;

    -- Get resource information
    v_resource_id := v_target_log.resource_id;
    v_before_snapshot := v_target_log.before_snapshot;
    v_after_snapshot := v_target_log.after_snapshot;

    -- Determine the target table based on resource_type (just table name, we'll use hr_public schema)
    v_resource_table := CASE v_target_log.resource_type
        WHEN 'events' THEN 'events'
        WHEN 'event' THEN 'events'
        WHEN 'tasks' THEN 'tasks'
        WHEN 'task' THEN 'tasks'
        WHEN 'leave_requests' THEN 'leave_requests'
        WHEN 'leave_request' THEN 'leave_requests'
        WHEN 'users' THEN 'users'
        WHEN 'profile' THEN 'users'
        WHEN 'employee' THEN 'users'
        WHEN 'departments' THEN 'departments'
        WHEN 'department' THEN 'departments'
        ELSE NULL
    END;

    IF v_resource_table IS NULL THEN
        RETURN QUERY SELECT FALSE, NULL::UUID, format('Unsupported resource type: %s', v_target_log.resource_type)::TEXT;
        RETURN;
    END IF;

    -- Execute the rollback based on the original action
    BEGIN
        IF UPPER(v_target_log.action) = 'CREATE' THEN
            -- Rollback CREATE = DELETE the resource
            EXECUTE format('DELETE FROM hr_public.%I WHERE id = $1', v_resource_table)
            USING v_resource_id;

            -- Create rollback activity log
            INSERT INTO hr_public.activity_logs (
                employee_id,
                user_id,
                action,
                resource_type,
                resource_id,
                before_snapshot,
                after_snapshot,
                is_rollback,
                rolled_back_log_id,
                details,
                ip_address,
                user_agent
            ) VALUES (
                v_current_user_id,
                v_current_user_id,
                'delete',
                v_target_log.resource_type,
                v_resource_id,
                v_after_snapshot, -- What it was before rollback
                NULL, -- Now it's deleted
                TRUE,
                p_log_id,
                jsonb_build_object(
                    'rollback_reason', p_reason,
                    'rollback_strategy', p_strategy,
                    'original_action', 'create'
                ),
                NULL,
                NULL
            ) RETURNING id INTO v_new_log_id;

        ELSIF UPPER(v_target_log.action) = 'DELETE' THEN
            -- Rollback DELETE = Re-CREATE the resource
            -- This is complex as we need to restore all fields
            EXECUTE format(
                'INSERT INTO hr_public.%I SELECT * FROM jsonb_populate_record(NULL::hr_public.%I, $1)',
                v_resource_table,
                v_resource_table
            ) USING v_before_snapshot;

            -- Create rollback activity log
            INSERT INTO hr_public.activity_logs (
                employee_id,
                user_id,
                action,
                resource_type,
                resource_id,
                before_snapshot,
                after_snapshot,
                is_rollback,
                rolled_back_log_id,
                details,
                ip_address,
                user_agent
            ) VALUES (
                v_current_user_id,
                v_current_user_id,
                'create',
                v_target_log.resource_type,
                v_resource_id,
                NULL,
                v_before_snapshot,
                TRUE,
                p_log_id,
                jsonb_build_object(
                    'rollback_reason', p_reason,
                    'rollback_strategy', p_strategy,
                    'original_action', 'delete'
                ),
                NULL,
                NULL
            ) RETURNING id INTO v_new_log_id;

        ELSIF UPPER(v_target_log.action) = 'UPDATE' THEN
            -- Rollback UPDATE = UPDATE to before_snapshot
            -- Build dynamic UPDATE statement
            DECLARE
                v_update_sql TEXT;
                v_set_clauses TEXT[];
                v_key TEXT;
                v_value TEXT;
            BEGIN
                -- Build SET clauses from before_snapshot
                FOR v_key, v_value IN SELECT * FROM jsonb_each_text(v_before_snapshot)
                LOOP
                    IF v_key != 'id' THEN -- Don't update the ID
                        v_set_clauses := array_append(
                            v_set_clauses,
                            format('%I = %L', v_key, v_value)
                        );
                    END IF;
                END LOOP;

                IF array_length(v_set_clauses, 1) > 0 THEN
                    v_update_sql := format(
                        'UPDATE hr_public.%I SET %s WHERE id = $1',
                        v_resource_table,
                        array_to_string(v_set_clauses, ', ')
                    );

                    EXECUTE v_update_sql USING v_resource_id;
                END IF;
            END;

            -- Create rollback activity log
            INSERT INTO hr_public.activity_logs (
                employee_id,
                user_id,
                action,
                resource_type,
                resource_id,
                before_snapshot,
                after_snapshot,
                is_rollback,
                rolled_back_log_id,
                details,
                ip_address,
                user_agent
            ) VALUES (
                v_current_user_id,
                v_current_user_id,
                'update',
                v_target_log.resource_type,
                v_resource_id,
                v_after_snapshot, -- Current state before rollback
                v_before_snapshot, -- Restored state
                TRUE,
                p_log_id,
                jsonb_build_object(
                    'rollback_reason', p_reason,
                    'rollback_strategy', p_strategy,
                    'original_action', 'update'
                ),
                NULL,
                NULL
            ) RETURNING id INTO v_new_log_id;

        ELSE
            RETURN QUERY SELECT FALSE, NULL::UUID, format('Unsupported action type: %s', v_target_log.action)::TEXT;
            RETURN;
        END IF;

        -- Success
        RETURN QUERY SELECT TRUE, v_new_log_id, NULL::TEXT;

    EXCEPTION
        WHEN OTHERS THEN
            RETURN QUERY SELECT FALSE, NULL::UUID, format('Rollback failed: %s', SQLERRM)::TEXT;
    END;
END;
$function$

CREATE OR REPLACE FUNCTION hr_public.prevent_batch_deletion()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF OLD.status IN ('completed', 'failed') THEN
        RAISE EXCEPTION 'Cannot delete a batch that has completed or failed (status: %)', OLD.status;
    END IF;
    RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION hr_public.validate_bulk_rollback_batch()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    array_len INTEGER;
BEGIN
    -- Rule 1: Calculate array length
    array_len := array_length(NEW.activity_log_ids, 1);

    -- Rule 2: Maximum 100 log IDs per batch
    IF array_len > 100 THEN
        RAISE EXCEPTION 'Maximum 100 log IDs per batch (got: %)', array_len;
    END IF;

    -- Rule 3: At least 1 log ID required
    IF array_len IS NULL OR array_len < 1 THEN
        RAISE EXCEPTION 'At least 1 log ID required for bulk rollback';
    END IF;

    -- Rule 4: total_count must equal array_length(activity_log_ids, 1)
    IF NEW.total_count != array_len THEN
        RAISE EXCEPTION 'total_count (%) must equal array length (%)', NEW.total_count, array_len;
    END IF;

    -- Rule 5: processed_count must equal successful_count + failed_count
    IF NEW.processed_count != (NEW.successful_count + NEW.failed_count) THEN
        RAISE EXCEPTION 'processed_count (%) must equal successful_count (%) + failed_count (%)',
            NEW.processed_count, NEW.successful_count, NEW.failed_count;
    END IF;

    -- Rule 6: completed_at must be NULL when status IN ('queued', 'in_progress')
    IF NEW.status IN ('queued', 'in_progress') AND NEW.completed_at IS NOT NULL THEN
        RAISE EXCEPTION 'completed_at must be NULL when status is queued or in_progress';
    END IF;

    -- Rule 7: completed_at must NOT be NULL when status IN ('completed', 'failed')
    IF NEW.status IN ('completed', 'failed') AND NEW.completed_at IS NULL THEN
        NEW.completed_at := now();
    END IF;

    -- Rule 8: Cannot modify completed/failed batches
    IF TG_OP = 'UPDATE' AND OLD.status IN ('completed', 'failed') AND NEW.status != OLD.status THEN
        RAISE EXCEPTION 'Cannot modify a batch that has completed or failed';
    END IF;

    RETURN NEW;
END;
$function$
